async function loadVideoUpscaleReadiness(model="realesrgan-x4plus",engine=state.videoUpscaleEngine){
 state.videoUpscaleEngine=engine;
 state.videoUpscaleReadinessLoading=true;
 try{
  state.videoUpscaleReadiness=await apiRequest<{enabled:boolean;ready:boolean;engine:string;ffmpegAvailable:boolean;ffprobeAvailable:boolean;model:string;modelReady:boolean;modelStatus:{reason?:string|null};limits:{maxFrames:number;maxDurationSeconds:number;maxOutputPixels:number;maxTempBytes:number;scales:number[]};limitsValid:boolean;temporalConsistency:string}>("/api/ai-video-upscale/readiness?engine="+encodeURIComponent(engine)+"&model="+encodeURIComponent(model));
 }catch(error){
  state.videoUpscaleReadiness=null;
  state.cloudMessage=error instanceof Error?error.message:"Video upscaling readiness could not be checked.";
 }finally{
  state.videoUpscaleReadinessLoading=false;
  if(state.tab==="enhance")render();
 }
}
