 const stage=(item:string[],done:boolean)=>'<article class="provenance-stage"><div class="provenance-stage-top"><b>'+item[0]+' · '+item[1]+'</b><em class="provenance-state '+(done?'complete':'gated')+'">'+(done?'Complete':'Release gate')+'</em></div><p>'+item[2]+'</p></article>';
