async function publishBriefToCloud(){
 const project=state.projects.find(item=>item.id===state.activeProject);
 if(!project){state.cloudMessage="Create or select a creative brief first.";state.tab="director";render();return;}
 state.cloudMessage="Saving the production brief and creative bible…";render();
 try{
  const duration=state.plan.match(/DURATION:\s*([^\n]+)/)?.[1]||"Not specified";
  const existingSettings=state.cloudProjects.find(item=>item.id===state.cloudProjectLinks[project.id]?.id)?.settings||{};
  const settings={...existingSettings,schemaVersion:1,creativeProduction:{version:3,project:{id:project.id,name:project.name,brief:project.brief,audience:project.audience,style:project.style,duration,created:project.created},blueprint:state.plan,creativeDNA:project.creativeDNA||null,shots:state.shots,characters:state.characters,variants:state.variants,seriesPlans:state.seriesPlans}};
  const link=state.cloudProjectLinks[project.id];
  let saved:{id:string;name:string;revision:number};
  if(link){
   const result=await apiRequest<{project:{id:string;name:string;revision:number}}>("/api/cloud/projects/"+link.id,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({expectedRevision:state.cloudProjects.find(item=>item.id===link.id)?.revision??link.revision,name:project.name,description:project.brief,settings})});
   saved=result.project;
  }else{
   const result=await apiRequest<{project:{id:string;name:string;revision:number}}>("/api/cloud/projects",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name:project.name,description:project.brief,settings})});
   saved=result.project;
  }
  state.cloudProjectLinks[project.id]={id:saved.id,revision:saved.revision};
  state.cloudProjectId=saved.id;state.cloudMessage="Production saved. Future saves update this same cloud project using revision checks.";
  save();state.tab="cloud";await loadCloudWorkspace();
 }catch(error){state.cloudMessage=error instanceof Error?error.message:"Could not save the production to cloud.";render();}
}
