document.addEventListener("input",e=>{const i=e.target as HTMLInputElement;if(i.id==="capability-search"){filterCapabilities();return;}if(i.id==="explore-search"){const q=i.value.trim().toLowerCase();document.querySelectorAll<HTMLElement>("[data-explore-text]").forEach(card=>{card.hidden=!!q&&!String(card.dataset.exploreText||"").includes(q);});return;}if(i.id==="explore-capability-search"){filterExploreCapabilities();}});
document.addEventListener("change",e=>{const i=e.target as HTMLSelectElement;if(i.id==="capability-domain")filterCapabilities();if(i.id==="explore-capability-domain")filterExploreCapabilities();});
function filterExploreCapabilities(){const q=($<HTMLInputElement>("#explore-capability-search")?.value||"").trim().toLowerCase();const domain=$<HTMLSelectElement>("#explore-capability-domain")?.value||"";const results=CAPABILITY_ATLAS.filter(item=>(!domain||item.domain===domain)&&(!q||[item.id,item.label,item.domain,item.evidence,item.readiness,...item.inputs.map(x=>x.role),...item.outputs.map(x=>x.role)].join(" ").toLowerCase().includes(q)));const list=$<HTMLElement>("#explore-capability-results");if(list)list.innerHTML=capabilityCards(results);const count=$<HTMLElement>("#explore-capability-count");if(count)count.textContent=results.length+" of "+CAPABILITY_ATLAS.length+" capabilities";}
function filterCapabilities(){
 const query=($<HTMLInputElement>("#capability-search")?.value||"").trim().toLowerCase();
 const domain=$<HTMLSelectElement>("#capability-domain")?.value||"";
 const items=CAPABILITY_ATLAS.filter(item=>(!domain||item.domain===domain)&&(!query||[item.id,item.label,item.domain,item.evidence,item.readiness,...item.inputs.map(x=>x.role),...item.outputs.map(x=>x.role),...(item.notes?[item.notes]:[])].join(" ").toLowerCase().includes(query)));
 const listEl=document.querySelector<HTMLElement>("#capability-list");
 if(listEl)listEl.innerHTML=capabilityCards(items);
 const count=document.querySelector<HTMLElement>("#capability-count");
 if(count)count.textContent=items.length+" of "+CAPABILITY_ATLAS.length+" capabilities";
}
