window.addEventListener("ev:project-changed",async event=>{
 const projectId=(event as CustomEvent<{projectId:string}>).detail?.projectId||"";
 try{
  const response=projectId?await loadCreativeDraft(projectId):null;
  if(projectId!==getCurrentProjectId())return;
  const hasLocal=state.projects.length+state.tasks.length+state.shots.length+state.characters.length>0||Boolean(state.prompt||state.plan||state.script||state.variants.length);
  if(response?.document&&Number(response.document.schemaVersion)===1){
   const doc=response.document;
   state.projects=(doc.creativeProjects as Project[])||[];
   state.tasks=(doc.tasks as Task[])||[];
   state.shots=(doc.shots as Shot[])||[];
   state.characters=(doc.characters as Character[])||[];
   state.prompt=String(doc.prompt||"");state.plan=String(doc.plan||"");state.script=String(doc.script||"");
   state.variants=Array.isArray(doc.variants)?doc.variants as string[]:[];
   state.brandKit=doc.brandKit&&typeof doc.brandKit==="object"?doc.brandKit as BrandKit:{name:"",tagline:"",voice:"",visualStyle:"",colors:{primary:"#202124",secondary:"#5F6368",accent:"#7C5CFC",background:"#FFFFFF",text:"#202124"},typography:{heading:"",body:""},logoAssetIds:[],prohibitedTerms:[],legalFooter:"",updatedAt:""};
   state.campaignTemplates=Array.isArray(doc.campaignTemplates)?doc.campaignTemplates as CampaignTemplate[]:[{id:"tpl-vertical",name:"Vertical short-form",channel:"TikTok / Reels / Shorts",aspectRatio:"9:16",width:1080,height:1920,maxDurationSeconds:60,safeArea:{top:12,right:8,bottom:18,left:8},subtitleSafeArea:true,enabled:true},{id:"tpl-youtube",name:"YouTube landscape",channel:"YouTube",aspectRatio:"16:9",width:1920,height:1080,maxDurationSeconds:900,safeArea:{top:5,right:5,bottom:8,left:5},subtitleSafeArea:true,enabled:true},{id:"tpl-square",name:"Square social",channel:"Instagram / Facebook",aspectRatio:"1:1",width:1080,height:1080,maxDurationSeconds:90,safeArea:{top:8,right:8,bottom:12,left:8},subtitleSafeArea:true,enabled:true},{id:"tpl-feed",name:"Portrait feed",channel:"Instagram / Facebook",aspectRatio:"4:5",width:1080,height:1350,maxDurationSeconds:90,safeArea:{top:8,right:8,bottom:14,left:8},subtitleSafeArea:true,enabled:true}];
  }else if(state.apiProjectId&&state.apiProjectId!==projectId){
   state.projects=[];state.tasks=[];state.shots=[];state.characters=[];state.prompt="";state.plan="";state.script="";state.variants=[];
   state.brandKit={name:"",tagline:"",voice:"",visualStyle:"",colors:{primary:"#202124",secondary:"#5F6368",accent:"#7C5CFC",background:"#FFFFFF",text:"#202124"},typography:{heading:"",body:""},logoAssetIds:[],prohibitedTerms:[],legalFooter:"",updatedAt:""};
   state.campaignTemplates=[{id:"tpl-vertical",name:"Vertical short-form",channel:"TikTok / Reels / Shorts",aspectRatio:"9:16",width:1080,height:1920,maxDurationSeconds:60,safeArea:{top:12,right:8,bottom:18,left:8},subtitleSafeArea:true,enabled:true},{id:"tpl-youtube",name:"YouTube landscape",channel:"YouTube",aspectRatio:"16:9",width:1920,height:1080,maxDurationSeconds:900,safeArea:{top:5,right:5,bottom:8,left:5},subtitleSafeArea:true,enabled:true},{id:"tpl-square",name:"Square social",channel:"Instagram / Facebook",aspectRatio:"1:1",width:1080,height:1080,maxDurationSeconds:90,safeArea:{top:8,right:8,bottom:12,left:8},subtitleSafeArea:true,enabled:true},{id:"tpl-feed",name:"Portrait feed",channel:"Instagram / Facebook",aspectRatio:"4:5",width:1080,height:1350,maxDurationSeconds:90,safeArea:{top:8,right:8,bottom:14,left:8},subtitleSafeArea:true,enabled:true}];
  }else if(!hasLocal){
   state.projects=[];state.tasks=[];state.shots=[];state.characters=[];state.prompt="";state.plan="";state.script="";state.variants=[];
   state.brandKit={name:"",tagline:"",voice:"",visualStyle:"",colors:{primary:"#202124",secondary:"#5F6368",accent:"#7C5CFC",background:"#FFFFFF",text:"#202124"},typography:{heading:"",body:""},logoAssetIds:[],prohibitedTerms:[],legalFooter:"",updatedAt:""};
   state.campaignTemplates=[{id:"tpl-vertical",name:"Vertical short-form",channel:"TikTok / Reels / Shorts",aspectRatio:"9:16",width:1080,height:1920,maxDurationSeconds:60,safeArea:{top:12,right:8,bottom:18,left:8},subtitleSafeArea:true,enabled:true},{id:"tpl-youtube",name:"YouTube landscape",channel:"YouTube",aspectRatio:"16:9",width:1920,height:1080,maxDurationSeconds:900,safeArea:{top:5,right:5,bottom:8,left:5},subtitleSafeArea:true,enabled:true},{id:"tpl-square",name:"Square social",channel:"Instagram / Facebook",aspectRatio:"1:1",width:1080,height:1080,maxDurationSeconds:90,safeArea:{top:8,right:8,bottom:12,left:8},subtitleSafeArea:true,enabled:true},{id:"tpl-feed",name:"Portrait feed",channel:"Instagram / Facebook",aspectRatio:"4:5",width:1080,height:1350,maxDurationSeconds:90,safeArea:{top:8,right:8,bottom:14,left:8},subtitleSafeArea:true,enabled:true}];
  }else{
   window.dispatchEvent(new CustomEvent("ev:save-creative-draft",{detail:{creativeProjects:state.projects,tasks:state.tasks,shots:state.shots,characters:state.characters,prompt:state.prompt,plan:state.plan,script:state.script,variants:state.variants,brandKit:state.brandKit,campaignTemplates:state.campaignTemplates}}));
  }
  state.apiProjectId=projectId;
  localStorage.setItem(KEY,JSON.stringify({...state,tab:"home"}));
  render();
 }catch(error){console.warn("Creative workspace load failed",error);}
});
